SELECT s1."c0" AS "id", s1."c1" AS "customer" FROM (SELECT s2."c0" AS "c0", s2."c4" AS "c1" FROM (SELECT s3."c0" AS "c0", s3."c1" AS "c1", s3."c2" AS "c2", s3."c3" AS "c3", (CASE WHEN (s3."c3" IS NULL) THEN 'unknown' ELSE s3."c3" END) AS "c4" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1", s4."c2" AS "c2", s5."c0" AS "c3" FROM (SELECT v."c0" AS "c0", v."c1" AS "c1", v."c2" AS "c2" FROM (VALUES (CAST(1 AS BIGINT), 'ada', CAST(30 AS BIGINT)), (CAST(2 AS BIGINT), 'bob', CAST(5 AS BIGINT)), (CAST(3 AS BIGINT), 'ada', CAST(NULL AS BIGINT))) AS v("c0", "c1", "c2")) AS s4 LEFT JOIN (SELECT v."c0" AS "c0" FROM (VALUES ('ada'), ('cy')) AS v("c0")) AS s5 ON (s4."c1" = s5."c0")) AS s3) AS s2) AS s1
